  'groupage', 'ordre', 'jour', 'heureFigee', 'creneauCalcule', 'creneauEnvoye', 'statutClient',
  'contraintes', 'jeton', 'derniereReponse', 'margeMin', 'adresseManuelle', 'lat', 'lon',
];

const texte = (v) => (v === null || v === undefined ? '' : String(v));
const nombre = (v) => (v === null || v === undefined || v === '' ? null : Number(v));

function jeton(alea = Math.random) {
  let s = '';
  while (s.length < 24) s += Math.floor(alea() * 36 ** 8).toString(36).padStart(8, '0');
  return s.slice(0, 24);
}

function accesDe(lieu) {
  return JSON.stringify({
    typeLogement: (lieu || {}).type_logement ?? null,
    etage: (lieu || {}).etage ?? null,
    ascenseur: (lieu || {}).ascenseur ?? null,
