    portageM: (lieu || {}).portage_m ?? null,
    monteMeuble: (lieu || {}).monte_meuble ?? null,
  });
}

function statutAdresse(adresse, porteUnNumero) {
  if (!adresse) return 'manquante';
  return porteUnNumero(adresse) ? 'ok' : 'a_verifier';
}

// Un dossier (batirDossier) → ses deux arrêts. `porteUnNumero` est injecté pour garder ce
// module indépendant de fiche.js côté nœud Code.
function arretsDepuisDossier(dossier, porteUnNumero) {
  const commun = {
    leadId: texte(dossier.nocrm_id),
    client: dossier.nom_complet || '',
    telephone: dossier.tel || '',
    email: dossier.email || '',
    notionId: dossier.notion_id || '',
    ref: texte(dossier.ref),
    sens: dossier.sens || '',
    volume: nombre(dossier.volume_m3),
    stockeDepot: Boolean(dossier.stocke_depot),
    fenetreTot: dossier.fenetre ? dossier.fenetre.tot || '' : '',
    fenetreTard: dossier.fenetre ? dossier.fenetre.tard || '' : '',
    notes: JSON.stringify(dossier.notes || []),
    manques: JSON.stringify(dossier.manques || []),
    transportHt: nombre((dossier.chiffres || {}).transport_ht),
    deplacementHt: nombre((dossier.chiffres || {}).deplacement_ht),
    ttc: nombre((dossier.chiffres || {}).ttc),
  };
  return [
    {
      ...commun,
      type: 'chargement',
      adresse: dossier.depart.adresse || '',
      adresseStatut: statutAdresse(dossier.depart.adresse, porteUnNumero),
      acces: accesDe(dossier.depart),
    },
    {
      ...commun,
      type: 'livraison',
      adresse: dossier.arrivee.adresse || '',
      adresseStatut: statutAdresse(dossier.arrivee.adresse, porteUnNumero),
      acces: accesDe(dossier.arrivee),
