}

const cle = (a) => `${a.leadId}|${a.type}`;

// Confronte ce que dit le CRM à ce que porte la base.
// Rend { aCreer, aMettreAJour, aSupprimer } : les arrêts d'un dossier sorti de la colonne ne
// sont supprimés que s'ils ne sont affectés à aucune tournée — une tournée en cours reste intacte.
function fusionnerImport(arretsLus, arretsExistants, maintenant = new Date().toISOString()) {
  const parCle = new Map((arretsExistants || []).map((a) => [cle(a), a]));
  const vus = new Set();
  const aCreer = [];
  const aMettreAJour = [];

  for (const lu of arretsLus || []) {
    vus.add(cle(lu));
    const existant = parCle.get(cle(lu));
    if (!existant) {
      aCreer.push({
        ...lu,
        groupage: '',
        ordre: 0,
        jour: '',
        heureFigee: '',
        creneauCalcule: '',
        creneauEnvoye: '',
        statutClient: 'a_informer',
        contraintes: '',
        jeton: jeton(),
        derniereReponse: '',
        margeMin: null,
        adresseManuelle: false,
        lat: null,
        lon: null,
        majLe: maintenant,
      });
      continue;
    }
    const maj = { id: existant.id };
    let change = false;
    for (const champ of CHAMPS_IMPORT) {
      // Une adresse corrigée à la main ou par le client ne se fait pas écraser par le CRM.
      if (champ === 'adresse' || (existant.adresseManuelle && champ === 'acces')) continue;
      if (texte(lu[champ]) !== texte(existant[champ])) {
        maj[champ] = lu[champ];
        change = true;
      }
    }
    if (!existant.adresseManuelle && texte(lu.adresse) !== texte(existant.adresse)) {
      maj.adresse = lu.adresse;
      maj.adresseStatut = lu.adresseStatut;
      maj.lat = null; // l'adresse a bougé : le géocodage est à refaire
      maj.lon = null;
      change = true;
    }
    if (!existant.jeton) {
      maj.jeton = jeton();
      change = true;
    }
    if (change) {
      maj.majLe = maintenant;
      aMettreAJour.push(maj);
    }
  }

  const aSupprimer = (arretsExistants || [])
    .filter((a) => !vus.has(cle(a)) && !texte(a.groupage))
    .map((a) => a.id);

  return { aCreer, aMettreAJour, aSupprimer };
}

