const CHAMPS_MODIFIABLES = ['groupage', 'ordre', 'jour', 'heureFigee', 'creneauCalcule',
  'statutClient', 'contraintes', 'margeMin', 'adresse', 'adresseStatut', 'adresseManuelle'];

const CHAMPS_TOURNEE = ['nom', 'axe', 'statut', 'dateDebut', 'dateFin', 'camion', 'jours', 'marges'];

const STATUTS_TOURNEE = ['brouillon', 'confirmee', 'en_cours', 'terminee'];

function cleTournee(dateDebut, axe, existantes = []) {
  const court = sansDiacritiques(axe)
    .split(/[^a-z0-9]+/)
    .filter(Boolean)
    .map((m) => m.slice(0, 3))
    .join('-');
  const base = `${(dateDebut || '').slice(0, 10) || 'sans-date'}-${court || 'axe'}`;
  let cleFinale = base;
  let n = 2;
  const prises = new Set(existantes.map((t) => t.cle));
  while (prises.has(cleFinale)) cleFinale = `${base}-${n++}`;
  return cleFinale;
}

function sansDiacritiques(s) {
  return String(s || '').normalize('NFD').replace(/\p{Mn}/gu, '').toLowerCase();
}

// Contrôle de version : deux personnes sur la même tournée ne doivent pas s'écraser.
// Rend { ok } ou { ok: false, code, message } destiné à une réponse HTTP 409.
function verifierVersion(tourneeEnBase, versionAttendue) {
  if (!tourneeEnBase) return { ok: false, code: 404, message: "Cette tournée n'existe plus." };
  const enBase = Number(tourneeEnBase.version || 0);
  if (Number(versionAttendue) !== enBase) {
    return {
      ok: false,
      code: 409,
      message: `Le plan a été modifié entre-temps (version ${enBase}, la page a la ${versionAttendue})`
        + `${tourneeEnBase.modifiePar ? ` par ${tourneeEnBase.modifiePar}` : ''} — recharge la page avant d'enregistrer.`,
    };
  }
  return { ok: true };
}

// Prépare l'écriture d'un enregistrement : ne laisse passer que les champs modifiables.
function preparerEnregistrement(charge, tourneeEnBase, qui, maintenant = new Date().toISOString()) {
  const v = verifierVersion(tourneeEnBase, charge.version);
  if (!v.ok) return v;

  const tournee = { id: tourneeEnBase.id, version: Number(tourneeEnBase.version || 0) + 1, modifiePar: qui || '', modifieLe: maintenant };
  for (const champ of CHAMPS_TOURNEE) {
    if (charge.tournee && charge.tournee[champ] !== undefined) tournee[champ] = charge.tournee[champ];
  }
  if (tournee.statut && !STATUTS_TOURNEE.includes(tournee.statut)) {
    return { ok: false, code: 400, message: `Statut de tournée inconnu : ${tournee.statut}` };
  }

  const arrets = [];
  for (const a of charge.arrets || []) {
    if (!a.id) return { ok: false, code: 400, message: 'Un arrêt sans identifiant ne peut pas être enregistré.' };
    const ligne = { id: a.id, majLe: maintenant };
    for (const champ of CHAMPS_MODIFIABLES) if (a[champ] !== undefined) ligne[champ] = a[champ];
    arrets.push(ligne);
  }
  return { ok: true, tournee, arrets };
}


