// Confronte ce que dit le CRM à ce que porte la base.
// Rend { aCreer, aMettreAJour, aSupprimer } : les arrêts d'un dossier sorti de la colonne ne
// sont supprimés que s'ils ne sont affectés à aucune tournée — une tournée en cours reste intacte.
function fusionnerImport(arretsLus, arretsExistants, maintenant = new Date().toISOString()) {
  const parCle = new Map((arretsExistants || []).map((a) => [cle(a), a]));
  const vus = new Set();
  const aCreer = [];
  const aMettreAJour = [];

  for (const lu of arretsLus || []) {
    vus.add(cle(lu));
    const existant = parCle.get(cle(lu));
