        margeMin: null,
        adresseManuelle: false,
        lat: null,
        lon: null,
        majLe: maintenant,
      });
      continue;
    }
    const maj = { id: existant.id };
    let change = false;
    for (const champ of CHAMPS_IMPORT) {
      // Une adresse corrigée à la main ou par le client ne se fait pas écraser par le CRM.
      if (champ === 'adresse' || (existant.adresseManuelle && champ === 'acces')) continue;
      if (texte(lu[champ]) !== texte(existant[champ])) {
        maj[champ] = lu[champ];
