    if (!existant.adresseManuelle && texte(lu.adresse) !== texte(existant.adresse)) {
      maj.adresse = lu.adresse;
      maj.adresseStatut = lu.adresseStatut;
      maj.lat = null; // l'adresse a bougé : le géocodage est à refaire
      maj.lon = null;
      change = true;
    }
    if (!existant.jeton) {
