const corps = $('Notion – corps de la fiche').all().map((i) => i.json);
const fichesLues = $('Fiche Notion trouvée ?').all().map((i) => i.json);
const demandes = $('Blocs à descendre').all().map((i) => i.json);
const reponsesEnfants = $input.all().map((i) => i.json);

// Enfants rangés par bloc parent, pour lignesDepuisBlocs.
const enfants = {};
demandes.forEach((d, i) => { enfants[d.blocId] = ((reponsesEnfants[i] || {}).results) || []; });

const corpsParPage = {};
fichesLues.forEach((f, i) => { corpsParPage[f.pageId] = ((corps[i] || {}).results) || []; });

const arrets = [];
const journal = [];
for (const f of fiches) {
  const blocs = f.pageId ? (corpsParPage[f.pageId] || []) : [];
  const lignes = lignesDepuisBlocs(blocs, enfants);
  const dossier = batirDossier(f.lead, f.page, lignes, f.souci);
  journal.push({ client: dossier.nom_complet, source: dossier.source, manques: dossier.manques.length });
  for (const a of arretsDepuisDossier(dossier, porteUnNumero)) arrets.push(a);
}
return [{ json: { arrets, journal } }];

