// Une tournée terminée s'efface avec ses arrêts : les données clients vivent dans le CRM,
// inutile d'en garder un double sur le serveur une fois la tournée passée.
// Une tournée encore vivante libère seulement ses dossiers : une suppression par erreur ne coûte rien.
const cle = $('Webhook · supprimer une tournée').first().json.body.cle;
const tournee = $input.all().map((i) => i.json).filter((r) => r && r.id)[0] || null;
const effacer = Boolean(tournee && tournee.statut === 'terminee');
// Un seul appel par table, filtré sur la tournée : pas de boucle, et rien ne casse si elle est vide.
return [{ json: { cle, effacer, groupage: '', ordre: 0, jour: '', heureFigee: '', creneauCalcule: '', majLe: new Date().toISOString() } }];
